ALTER TABLE orders ADD COLUMN logistics_status TEXT NOT NULL DEFAULT 'WAITING_PAYMENT';
UPDATE orders SET logistics_status=CASE status WHEN 'PENDING_PAYMENT' THEN 'WAITING_PAYMENT' WHEN 'PAID' THEN 'PREPARING' WHEN 'SHIPPED' THEN 'OUT_FOR_DELIVERY' WHEN 'COMPLETED' THEN 'COMPLETED' WHEN 'CANCELLED' THEN 'CANCELLED' ELSE 'WAITING_PAYMENT' END;
